draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // book
  ctx.fillStyle = '#ccc';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-150, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-130);
  ctx.lineTo(W/2, H/2-80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2-30, H/2-50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2+30, H/2-50);
  ctx.stroke();

  // applying wisdom
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Applying Wisdom', W/2, H/2+50 + 20*Math.sin(t));

  // book opening
  ctx.fillStyle = '#ccc';
  ctx.fillRect(W/2-40, H/2-40, 20, 20);
  ctx.strokeRect(W/2-40, H/2-40, 20, 20);
  ctx.fillRect(W/2+20, H/2-40, 20, 20);
  ctx.strokeRect(W/2+20, H/2-40, 20, 20);
  ctx.fillRect(W/2-40, H/2-40, 20, 20);
  ctx.translate(W/2, H/2-40);
  ctx.rotate(Math.sin(t));
  ctx.fillRect(-10, -10, 20, 20);
  ctx.strokeRect(-10, -10, 20, 20);
  ctx.resetTransform();

  ctx.restore();
}
